<?php
declare(strict_types=1);
require __DIR__ . '/bootstrap.php';
$token=trim((string)($_GET['t']??$_POST['t']??''));$application=null;
if($token!==''){$stmt=$pdo->prepare("SELECT a.*,o.name organisation_name,TRIM(CONCAT(COALESCE(p.first_name,''),' ',COALESCE(p.last_name,''))) person_name,h.name horse_name FROM external_recognition_applications a LEFT JOIN recognised_organisations o ON o.id=a.organisation_id LEFT JOIN people p ON p.id=a.person_id LEFT JOIN horses h ON h.id=a.horse_id WHERE a.verification_token_hash=:hash AND a.status='awaiting_verification' AND a.verification_requested_at>=DATE_SUB(NOW(),INTERVAL 14 DAY)");$stmt->execute([':hash'=>hash('sha256',$token)]);$application=$stmt->fetch()?:null;}
$message='';
if($application&&$_SERVER['REQUEST_METHOD']==='POST'){$decision=(string)($_POST['decision']??'');if(in_array($decision,['verified','rejected'],true)){$stmt=$pdo->prepare("UPDATE external_recognition_applications SET status=:status,verified_at=IF(:status2='verified',NOW(),verified_at),reviewed_at=NOW(),verification_token_hash=NULL WHERE id=:id");$stmt->execute([':status'=>$decision,':status2'=>$decision,':id'=>$application['id']]);$message=$decision==='verified'?'The credential has been verified.':'The credential has been rejected.';$application=null;}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Credential verification</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:720px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h4">External credential verification</h1><?php if($message): ?><div class="alert alert-success"><?php echo h($message); ?></div><?php elseif(!$application): ?><div class="alert alert-danger">This verification link is invalid or has expired.</div><?php else: ?><p>Please confirm whether this credential is valid.</p><dl class="row"><dt class="col-sm-4">Organisation</dt><dd class="col-sm-8"><?php echo h((string)$application['organisation_name']); ?></dd><dt class="col-sm-4">For</dt><dd class="col-sm-8"><?php echo h((string)($application['person_name']?:$application['horse_name'])); ?></dd><dt class="col-sm-4">Credential</dt><dd class="col-sm-8"><?php echo h((string)$application['credential_number']); ?></dd><dt class="col-sm-4">Valid until</dt><dd class="col-sm-8"><?php echo h(format_display_date($application['valid_until'])); ?></dd></dl><form method="post" class="d-flex gap-2"><input type="hidden" name="t" value="<?php echo h($token); ?>"><button class="btn btn-success" name="decision" value="verified">Confirm valid</button><button class="btn btn-outline-danger" name="decision" value="rejected">Reject</button></form><?php endif; ?></div></div></main></body></html>
